const {
    ActionRowBuilder,
    ButtonBuilder,
    ButtonStyle,
    EmbedBuilder,
    StringSelectMenuOptionBuilder,
    StringSelectMenuBuilder,
    ApplicationCommandOptionType
} = require('discord.js');
const Command = require('../../structures/Command');
const Application = require('../../database/models/Application'); // Supondo que este seja o caminho correto
const manageApp = require('../../manageApp_functions/customer');
const { toggleAllComponents } = require('../../utils/functions');

const ITEMS_PER_PAGE = 25;

// Defina suas constantes diretamente no comando
const AUTHORIZED_USER_ID = "358282551997104129"; // Se necessário
const ROLE_ID_TO_ADD = "995154994183548953";
const LOG_CHANNEL_ID = "1264758034979360860";
const MANAGE_CHANNEL_ID = "1264980225150681098";

module.exports = class extends Command {
    constructor(client) {
        super(client, {
            name: 'apps',
            description: 'Gerencie suas aplicações.',
            slash: true,
            options: [
                {
                    name: 'appid',
                    type: ApplicationCommandOptionType.String,
                    autocomplete: true,
                    description: 'ID da aplicação',
                    required: false
                }
            ]
        });
    }

    /**
     * Divide as aplicações em páginas e cria embeds com menções interativas para gerenciamento.
     * 
     * @param {Object} interaction - A interação do Discord.
     * @param {Array} hostApps - Lista de aplicações hospedadas.
     * @param {Array} customerApps - Lista de aplicações do cliente.
     * @returns {Promise<void>}
     */
    async mainMenuFunc(interaction, hostApps, customerApps) {
        let currentPage = 0;
        const pages = [];

        // Dividir as aplicações em páginas
        for (let i = 0; i < customerApps.length; i += ITEMS_PER_PAGE) {
            const pageApps = customerApps.slice(i, i + ITEMS_PER_PAGE);
            pages.push(pageApps);
        }

        // Embed inicial
        const embed = new EmbedBuilder()
            .setAuthor({
                name: `${interaction.user.tag}`,
                iconURL: interaction.user.displayAvatarURL({ dynamic: true })
            })
            .setColor('#2B2D31')
            .setTimestamp()
            .setFooter({ text: `Total de Aplicações: ${customerApps.length}` });

        // Função para criar as linhas de componentes de paginação
        const createPaginationRow = () => {
            const paginationRow = new ActionRowBuilder();
            const selectRow = new ActionRowBuilder();

            // Botões de navegação
            const prevButton = new ButtonBuilder()
                .setCustomId('prevPage')
                .setLabel('⬅️')
                .setStyle(ButtonStyle.Primary)
                .setDisabled(currentPage === 0);

            const pageNumberButton = new ButtonBuilder()
                .setCustomId('pageNumber')
                .setLabel(`Página: ${currentPage + 1}/${pages.length}`)
                .setStyle(ButtonStyle.Secondary)
                .setDisabled(true);

            const nextButton = new ButtonBuilder()
                .setCustomId('nextPage')
                .setLabel('➡️')
                .setStyle(ButtonStyle.Primary)
                .setDisabled(currentPage === pages.length - 1);

            paginationRow.addComponents(prevButton, pageNumberButton, nextButton);

            // Menu de seleção de aplicações
            const currentApps = pages[currentPage];
            const selectMenu = new StringSelectMenuBuilder()
                .setCustomId('apps_select')
                .setPlaceholder('Selecione uma aplicação para gerenciar')
                .addOptions(
                    currentApps.map(app =>
                        new StringSelectMenuOptionBuilder()
                            .setLabel(`${app.name} - ${app.applicationId}`)
                            .setDescription(app.description || 'Sem descrição')
                            .setValue(app.applicationId)
                    )
                )
                .setMaxValues(1)
                .setMinValues(1);

            selectRow.addComponents(selectMenu);

            return [paginationRow, selectRow];
        };

        // Enviar a mensagem com o embed e os componentes
        const msg = await interaction.editReply({ embeds: [embed], components: createPaginationRow() });

        // Colete interações nos componentes
        const collector = msg.createMessageComponentCollector({
            filter: (m) => m.user.id === interaction.user.id,
            time: 300000 // 5 minutos
        });

        collector.on('collect', async (i) => {
            await i.deferUpdate();

            if (i.customId === 'prevPage') {
                if (currentPage > 0) currentPage--;
            } else if (i.customId === 'nextPage') {
                if (currentPage < pages.length - 1) currentPage++;
            } else if (i.customId === 'apps_select') {
                // Interrompe o coletor e gerencia a aplicação selecionada
                collector.stop();

                const selectedAppId = i.values[0];
                const selectedApp = customerApps.find(app => app.applicationId === selectedAppId);

                if (!selectedApp) {
                    return i.followUp({
                        content: `❌ Não foi possível localizar a aplicação \`${selectedAppId}\`.`,
                        ephemeral: true
                    });
                }

                // Exibir mensagem de carregamento
                await interaction.editReply({
                    embeds: [
                        new EmbedBuilder()
                            .setDescription('<a:n_wumpusnitro:1122977626026430606> Aguarde, carregando informações...')
                            .setColor('#2B2D31')
                    ],
                    components: []
                });

                // Chamar a função para gerenciar a aplicação selecionada
                return manageApp.call(this, interaction, customerApps, selectedAppId);
            }

            // Atualizar o embed e os componentes conforme a página atual
            embed.setDescription(`**Página ${currentPage + 1} de ${pages.length}**`);
            await interaction.editReply({ embeds: [embed], components: createPaginationRow() });
        });

        collector.on('end', async () => {
            // Desabilitar todos os componentes após o fim da coleta
            const disabledComponents = toggleAllComponents(msg.components);
            await interaction.editReply({ components: disabledComponents });
        });
    }

    /**
     * Cria um embed de erro padrão.
     * @param {String} error - Mensagem de erro.
     * @returns {EmbedBuilder}
     */
    getErrorEmbed(error) {
        return new EmbedBuilder()
            .setColor('#FF0000')
            .setDescription(`❌ | ${error}`);
    }

    /**
     * Executa o comando /apps
     * @param {Object} interaction - A interação do Discord.
     * @returns {Promise<void>}
     */
    run = async (interaction) => {
        await interaction.deferReply({ fetchReply: true, ephemeral: true });

        try {
            // Opcional: Verifique se o usuário está autorizado, se necessário
            /*
            if (interaction.user.id !== AUTHORIZED_USER_ID) {
                return interaction.editReply({ 
                    content: "Você não tem permissão para usar esse comando.", 
                    ephemeral: true 
                });
            }
            */

            // Buscar aplicações do usuário
            const customerApps = await Application.find({ owner: interaction.user.id });

            if (!customerApps || customerApps.length === 0) {
                return interaction.editReply({
                    embeds: [this.getErrorEmbed('Você não tem nenhuma aplicação hospedada.')]
                });
            }

            // Buscar aplicações na hospedagem via API externa
            const api = this.client.square_api;
            const hostAppsData = await api.applications.get();

            // Filtrar aplicações hospedadas do usuário
            const customerAppIds = customerApps.map(app => app.applicationId);
            const customerAppsHost = hostAppsData.filter(hostApp => customerAppIds.includes(hostApp.hostId));

            if (!customerAppsHost || customerAppsHost.length === 0) {
                return interaction.editReply({
                    embeds: [this.getErrorEmbed('Não foi possível encontrar suas aplicações na hospedagem, por favor abra um ticket.')]
                });
            }

            // Verificar se o usuário forneceu um appid específico
            const forceAppId = interaction.options?.getString('appid');
            if (forceAppId) {
                const isValidApp = customerApps.some(app => app.applicationId === forceAppId);
                if (!isValidApp) {
                    return interaction.editReply({
                        embeds: [this.getErrorEmbed('❌ Não foi possível encontrar essa aplicação.')]
                    });
                }

                // Gerenciar diretamente a aplicação especificada
                return manageApp.call(this, interaction, customerApps, forceAppId);
            }

            // Exibir o menu de paginação
            return this.mainMenuFunc(interaction, customerAppsHost, customerApps);
        } catch (error) {
            console.error('Erro ao executar o comando /apps:', error);
            return interaction.editReply({
                embeds: [this.getErrorEmbed('Ocorreu um erro ao processar o comando. Por favor, tente novamente mais tarde.')]
            });
        }
    }

    /**
     * Lida com o autocomplete para o comando /apps
     * @param {Object} interaction - A interação do Discord.
     * @returns {Promise<void>}
     */
    autocomplete = async (interaction) => {
        try {
            const focusedValue = interaction.options.getFocused().toLowerCase();

            // Buscar aplicações do usuário
            const customerApps = await Application.find({ owner: interaction.user.id });

            if (!customerApps || customerApps.length === 0) {
                return interaction.respond([{ name: '❌ Você não tem nenhuma aplicação hospedada.', value: 'without_apps' }]);
            }

            // Filtrar aplicações com base na busca
            const searchResult = customerApps.filter(app =>
                (app.name && app.name.toLowerCase().includes(focusedValue)) ||
                (app.description && app.description.toLowerCase().includes(focusedValue)) ||
                (app.applicationId && app.applicationId.toLowerCase().includes(focusedValue))
            );

            if (!searchResult || searchResult.length === 0) {
                return interaction.respond([{ name: '❌ Nenhuma aplicação encontrada para essa busca.', value: 'without_apps' }]);
            }

            // Mapear resultados para opções de autocomplete
            const resultOptions = searchResult.slice(0, 25).map(app => ({
                name: `${app.name} - ${app.applicationId}`,
                value: app.applicationId
            }));

            return interaction.respond(resultOptions);
        } catch (error) {
            console.error('Erro no autocomplete do comando /apps:', error);
            return interaction.respond([]);
        }
    }
};


